#!/usr/bin/env node

/**
 * Advanced scraper for Onshape FeatureScript documentation
 * Supports both static HTML parsing and dynamic content via Puppeteer
 * Usage: node scrapeFeatureScriptDocs-advanced.mjs [--browser]
 * 
 * Generated by Claude Haiku 4.5
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const useBrowser = process.argv.includes('--browser');
const DOCS_URL = 'https://cad.onshape.com/FsDoc/library.html';
const OUTPUT_FILE = path.join(__dirname, '..', '..', 'src', 'app', 'onshape', 'featurescript-library.json');

let cheerio;
try {
  cheerio = (await import('cheerio')).default;
  if (!cheerio) {
    const module = await import('cheerio');
    cheerio = module.load ? module : module.default;
  }
  if (!cheerio || !cheerio.load) {
    throw new Error('Cheerio does not have load method');
  }
} catch (e) {
  console.error('Error importing cheerio:', e.message);
  process.exit(1);
}

/**
 * Fetch HTML content - try static first, then dynamic if needed
 */
async function fetchPageContent() {
  console.log(`Fetching ${DOCS_URL}...`);
  
  // Try static fetch first
  try {
    const response = await fetch(DOCS_URL, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
      }
    });
    
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    
    const html = await response.text();
    if (html.length > 5000) {
      console.log(`✓ Static fetch successful (${(html.length / 1024).toFixed(2)} KB)`);
      return html;
    } else {
      throw new Error('Content too small, likely dynamic');
    }
  } catch (error) {
    if (useBrowser) {
      console.log(`Static fetch failed: ${error.message}`);
      return await fetchWithPuppeteer();
    }
    throw error;
  }
}

/**
 * Fetch using Puppeteer for dynamic content
 */
async function fetchWithPuppeteer() {
  console.log('Using Puppeteer for dynamic content rendering...');
  
  try {
    const puppeteer = await import('puppeteer');
    const browser = await puppeteer.default.launch({
      headless: 'new',
      args: ['--no-sandbox', '--disable-setuid-sandbox']
    });
    
    const page = await browser.newPage();
    await page.goto(DOCS_URL, { waitUntil: 'networkidle2', timeout: 30000 });
    const html = await page.content();
    await browser.close();
    
    console.log(`✓ Puppeteer fetch successful (${(html.length / 1024).toFixed(2)} KB)`);
    return html;
  } catch (error) {
    console.error(`Puppeteer failed: ${error.message}`);
    console.error('Install puppeteer with: pnpm install --save-dev puppeteer');
    throw error;
  }
}

/**
 * Parse parameters from function signature string
 * Example: "(feature is function, defaults is map)" 
 * Returns: [{name: "feature", type: "function"}, {name: "defaults", type: "map"}]
 */
function parseParametersFromSignature(signature) {
  const params = [];
  
  if (!signature || !signature.includes('(')) {
    return params;
  }
  
  // Extract content between parentheses
  const match = signature.match(/\((.*)\)\s*(?:=>|returns?)?/i);
  if (!match || !match[1]) {
    return params;
  }
  
  const paramStr = match[1].trim();
  if (!paramStr) {
    return params;
  }
  
  // Split by comma, but be careful with nested types like Map<String, Type>
  let depth = 0;
  let current = '';
  
  for (let i = 0; i < paramStr.length; i++) {
    const char = paramStr[i];
    
    if (char === '<' || char === '[') {
      depth++;
      current += char;
    } else if (char === '>' || char === ']') {
      depth--;
      current += char;
    } else if (char === ',' && depth === 0) {
      // This is a parameter separator
      const paramPart = current.trim();
      if (paramPart) {
        const param = parseParameterDeclaration(paramPart);
        if (param) {
          params.push(param);
        }
      }
      current = '';
    } else {
      current += char;
    }
  }
  
  // Don't forget the last parameter
  if (current.trim()) {
    const param = parseParameterDeclaration(current.trim());
    if (param) {
      params.push(param);
    }
  }
  
  return params;
}

/**
 * Parse a single parameter declaration like "feature is function" or "count is number"
 * Returns: {name: "feature", type: "function"} or null if invalid
 */
function parseParameterDeclaration(paramDecl) {
  // Pattern: name is type [optional default]
  // Examples: "feature is function", "defaults is map", "shouldFillet is boolean"
  
  const parts = paramDecl.split(/\s+is\s+/i);
  if (parts.length < 2) {
    // Might be just a type without "is"
    const tokens = paramDecl.trim().split(/\s+/);
    if (tokens.length === 1) {
      return { name: tokens[0], type: tokens[0] };
    }
    return null;
  }
  
  const name = parts[0].trim();
  const typeAndDefault = parts.slice(1).join(' is ').trim();
  
  // Extract just the type (before any =, [, or other modifiers)
  const type = typeAndDefault.split(/[\s=\[\]]/)[0].trim();
  
  if (name && type) {
    return { name, type, description: '' };
  }
  
  return null;
}

/**
 * Parse parameter table from HTML
 */
function parseParameterTable($, table) {
  const params = [];
  const rows = $(table).find('tbody tr, tr');
  
  rows.each((i, row) => {
    const cells = $(row).find('td, th');
    if (cells.length >= 2) {
      const param = {
        name: $(cells[0]).text().trim(),
        type: $(cells[1]).text().trim(),
        description: cells[2] ? $(cells[2]).text().trim() : ''
      };
      
      if (param.name && !param.name.includes('Parameter') && !param.name.includes('Type')) {
        params.push(param);
      }
    }
  });
  
  return params;
}

/**
 * Parse a node signature element (function/type definition)
 */
function parseNodeSignature($, elem) {
  const $elem = $(elem);
  
  // Get symbol name
  const name = $elem.find('.fs-symbol-name').first().text().trim();
  
  // Get symbol descriptor (type, predicate, function, etc.)
  const descriptor = $elem.find('.fs-symbol-descriptor').first().text().trim();
  
  // Get function arguments (the full signature)
  const functionArgs = $elem.find('.fs-function-arguments').first().text().trim();
  
  // Get return type
  const returnInfo = $elem.find('.fs-function-return').first().text().trim();
  
  // Get description from next doc-content or preceding text
  let description = '';
  const docContent = $elem.next('.fs-doc-content, div');
  if (docContent.length > 0) {
    description = docContent.find('p').first().text().trim();
    if (!description) {
      description = docContent.text().trim().substring(0, 200);
    }
  }
  
  // Parse parameters - first from signature, then merge with HTML table descriptions
  let parameters = parseParametersFromSignature(functionArgs);
  
  // Look for parameter descriptions in HTML tables
  const tableParams = [];
  if (docContent.length > 0) {
    docContent.find('table').each((i, table) => {
      const tableP = parseParameterTable($, table);
      tableParams.push(...tableP);
    });
  }
  
  // Merge: use table descriptions if available, otherwise keep signature-only params
  if (tableParams.length > 0) {
    // Match parameters by name and add descriptions
    parameters = parameters.map(param => {
      const tableParam = tableParams.find(tp => tp.name === param.name);
      return {
        ...param,
        description: tableParam?.description || param.description || ''
      };
    });
    
    // Also add any table params not found in signature (in case of parsing issues)
    for (const tableParam of tableParams) {
      if (!parameters.find(p => p.name === tableParam.name)) {
        parameters.push(tableParam);
      }
    }
  }
  
  return {
    name,
    descriptor,
    signature: functionArgs,
    returnType: returnInfo.replace(/returns?/i, '').trim(),
    description,
    parameters
  };
}

/**
 * Parse a file section (fs-file)
 */
function parseFileSection($, fileElem) {
  const $file = $(fileElem);
  
  // Get file header
  const fileName = $file.find('.file-header').first().text().trim();
  
  // Get file description (first paragraph after header)
  const fileDesc = $file.find('p').first().text().trim();
  
  // Parse all node signatures in this file
  const entries = [];
  $file.find('p.node-signature').each((i, elem) => {
    try {
      const entry = parseNodeSignature($, elem);
      if (entry.name) {
        entries.push(entry);
      }
    } catch (error) {
      // Skip parsing errors
    }
  });
  
  return {
    fileName,
    description: fileDesc,
    entries
  };
}

/**
 * Parse documentation structure
 */
function parseDocumentation(html) {
  const $ = cheerio.load(html);
  
  // Parse categories from sidebar
  const categories = [];
  const categoryMap = new Map();
  
  // Find all fs-section-heading elements in sidebar
  $('.fs-sidebar .fs-section-heading').each((i, heading) => {
    const categoryName = $(heading).text().trim();
    const categoryId = categoryName.toLowerCase().replace(/\s+/g, '-');
    
    const category = {
      id: categoryId,
      name: categoryName,
      files: []
    };
    
    categoryMap.set(categoryId, category);
    categories.push(category);
  });
  
  // Parse all fs-category sections
  $('.fs-doc-body .fs-category').each((i, catElem) => {
    const categoryId = $(catElem).attr('id')?.replace('category-', '').toLowerCase().replace(/\s+/g, '-');
    const category = categoryMap.get(categoryId);
    if (!category) return;
    
    // Parse all file sections in this category
    $(catElem).find('.fs-file').each((j, fileElem) => {
      const fileData = parseFileSection($, fileElem);
      if (fileData.entries.length > 0 || fileData.fileName) {
        category.files.push(fileData);
      }
    });
  });
  
  return categories;
}

/**
 * Main execution
 */
async function main() {
  try {
    const html = await fetchPageContent();
    console.log('Parsing documentation...');
    
    const categories = parseDocumentation(html);
    
    const documentation = {
      source: DOCS_URL,
      fetchedAt: new Date().toISOString(),
      parseMethod: useBrowser ? 'puppeteer' : 'static',
      categories,
      metadata: {
        totalCategories: categories.length,
        totalFiles: categories.reduce((sum, cat) => sum + cat.files.length, 0),
        totalEntries: categories.reduce((sum, cat) => 
          sum + cat.files.reduce((fsum, file) => fsum + file.entries.length, 0), 0
        )
      }
    };
    
    // Ensure output directory exists
    const outputDir = path.dirname(OUTPUT_FILE);
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }
    
    // Write JSON file
    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(documentation, null, 2), 'utf-8');
    
    console.log('\n✓ Documentation extracted successfully!');
    console.log(`  Output: ${OUTPUT_FILE}`);
    console.log(`  Categories: ${documentation.metadata.totalCategories}`);
    console.log(`  Files: ${documentation.metadata.totalFiles}`);
    console.log(`  Entries: ${documentation.metadata.totalEntries}`);
    
  } catch (error) {
    console.error('\n✗ Error:', error.message);
    process.exit(1);
  }
}

// Run immediately when this script is executed
await main();
